const syntheticContent=(id:string,topic:string,n:number)=>({id,topic,title:`Synthetic approved feature ${n}`,hook:`Synthetic approved opening ${n}`,body:`Synthetic approved explanation ${n}`,cta:'Review the synthetic project',disclaimer:'Recordkeeping education. Not tax advice.',lessons:['Recordkeeping education. Not tax advice.',`Synthetic approved workflow step ${n}`],source:'Synthetic human-reviewed fixture package'});
function syntheticFixture(){
 const approvedContent=[syntheticContent('reviewed-synthetic-a','Business purpose in expense entry',1),syntheticContent('reviewed-synthetic-b','Expense category organization',2)];
 const profile:ProjectProfile={id:'gigwise',name:'Synthetic GigWise',enabled:true,colors:{background:'#ffffff',ink:'#111111',accent:'#cc3300',muted:'#777777'},typography:{display:'Synthetic Display',body:'Synthetic Body',mono:'Synthetic Mono'},logo:{type:'wordmark',value:'SYNTHETIC'},voice:['Synthetic fixture voice'],templates:['announcement'],restrictions:[],cta:'Review the synthetic project',assetDirectories:[],output:{width:1080,height:1920,fps:30},approvedContent,brandSources:['synthetic-fixture.md']};
 const texts=[...new Set(approvedContent.flatMap(c=>[c.title,c.hook,c.body,c.cta,c.disclaimer,...c.lessons]))];
 const claims=texts.map((text,i)=>({id:`synthetic-claim-${i}`,projectId:profile.id,kind:(text===profile.cta?'cta':'marketing') as 'cta'|'marketing',sourceId:'synthetic-source',path:'synthetic-fixture.md',locator:`lines:${i+1}-${i+1}`,sha256:'a'.repeat(64),text}));
 const knowledge:ProjectKnowledge={projectId:profile.id,status:'COMPLETE',scope:'Synthetic test-only approved evidence',refreshReasons:[],claims,description:['Synthetic description'],audience:['Synthetic operators'],verifiedCapabilities:texts,approvedMarketing:texts,prohibitedClaims:[],voice:['Synthetic fixture voice'],assets:[],templates:['announcement'],ctas:[profile.cta],snapshotHash:'synthetic-snapshot-v1',refreshedAt:'2026-10-11T00:00:00Z'};
 return {profile,knowledge,plans:creativePlans(profile,knowledge)};
}
function proposalFor(plan:ReturnType<typeof creativePlans>[number],profile:ProjectProfile,knowledge:ProjectKnowledge,slotId:string,variant=0):CampaignProposal{const selected=plan.variants[variant]!;return proposalSchema.parse({projectId:profile.id,title:plan.hook,contentAngle:plan.concept,category:plan.approach.narrative,audience:knowledge.audience[0],hook:selected.scenes[0]!.headline,script:{version:1,projectId:profile.id,topic:plan.concept,contentId:'campaign:'+slotId,template:plan.template,cta:profile.cta,scenes:selected.scenes},storyboard:selected.storyboard,requiredAssets:plan.requiredAssets,durationSeconds:selected.durationSeconds,caption:plan.caption,hashtags:['#SyntheticFixture','#ApprovedEvidence'],cta:profile.cta,ctaDestination:null,sourceClaimIds:plan.sourceClaimIds,creativeApproach:plan.approach,acceptedChanges:[],rejectedChanges:[]});}
function concept(coreA:string,coreB:string,layoutA='sequence',layoutB='focus'):ComparableConcept{const scenes:VideoScript['scenes']=[{kind:'hook',headline:'Shared feature opening',body:'Approved context',seconds:4,layout:'headline'},{kind:'lesson',headline:coreA,body:coreA,seconds:8,layout:layoutA as any},{kind:'lesson',headline:coreB,body:coreB,seconds:8,layout:layoutB as any},{kind:'cta',headline:'Approved close',body:'Review',seconds:4,layout:'headline'}];return {projectId:'synthetic-project',contentAngle:'Shared feature workflow',audience:'Synthetic operators',hook:'Shared feature opening',script:{version:1,projectId:'synthetic-project',topic:'Shared feature workflow',contentId:'synthetic',template:'announcement',cta:'Review',scenes},storyboard:scenes.map(s=>({visual:s.layout??'focus'}))};}
const validation=(passed=true):CampaignValidation=>({passed,errors:passed?[]:['Duplicate concept'],warnings:[],availableAssets:[],missingAssets:[],renderingReady:passed,productionEligible:false,fingerprint:'synthetic',duplicateIds:[],checkedAt:'2026-10-11T00:00:00Z',snapshotHash:'synthetic-snapshot-v1',durationSeconds:24,criteria:{}});
function saveSlot(store:JobStore,slot:CampaignSlot){store.db.prepare('UPDATE campaign_slots SET status=?,data=? WHERE id=?').run(slot.status,JSON.stringify(slot),slot.id);}
// Fixture-only deadline avoids dependence on the production campaign calendar.
function initializeFixture(service:CampaignService){service.initialize();service.store.db.prepare("UPDATE campaigns SET data=json_set(data,'$.deadline','2099-10-12T17:00:00.000Z') WHERE id=?").run(campaignId);}

class PendingCenter{contracts=new Map<string,EditorialJob>();submissions:string[]=[];async submit(job:EditorialJob):Promise<EditorialResult>{const old=this.contracts.get(job.jobId);if(old)assert.deepEqual(job,old);else this.contracts.set(job.jobId,job);this.submissions.push(job.jobId);return {version:1,jobId:job.jobId,state:'pending',readyForConsumer:false,result:null,raw:null,error:null,contract:job,lifecycle:{sessionId:null,state:null,verifiedUnloadAt:null,cleanupError:null,blocker:null,loadMs:null,inferMs:null,unloadMs:null},createdAt:'2026-10-11T00:00:00Z',completedAt:null};}async get(id:string):Promise<EditorialResult>{throw new Error(id);}async cancel(id:string):Promise<EditorialResult>{throw new Error(id);}async status():Promise<CenterStatus>{return {version:1,workerActive:true,queue:{counts:{},running:null},resource:{blocker:null},activeSession:null,lastCompletedJob:null,models:[]};}}
function wire(service:CampaignService,knowledge:ProjectKnowledge){(service as any).knowledge={load:async()=>knowledge};}

test('structured distinctness separates exact, near, superficial, related and genuinely distinct concepts',()=>{const base=concept('organize the shared feature record with date purpose and receipt','connect the shared feature receipt to its matching expense'),exact=structuredClone(base),near=structuredClone(base),superficial=concept('organize the shared feature record with date purpose and receipt','connect the shared feature receipt to its matching expense','comparison','relationship'),distinct=concept('review category groups before exporting an approved record','filter the record list by a separate category workflow','relationship','sequence');near.script!.scenes[1]!.headline+=' carefully';assert.equal(compareConcept(base,exact,'exact').classification,'EXACT_DUPLICATE');assert.equal(compareConcept(base,near,'near').classification,'NEAR_DUPLICATE');assert.equal(compareConcept(base,superficial,'superficial').classification,'SUPERFICIAL_REWRITE');assert.equal(compareConcept(base,distinct,'distinct').classification,'DISTINCT');const openingOnly=structuredClone(base);openingOnly.hook='A completely different approved opening';assert.equal(compareConcept(base,openingOnly,'opening-only').classification,'SUPERFICIAL_REWRITE');const partial={projectId:base.projectId,contentAngle:base.contentAngle,storyboard:[]};const assessment=assessDistinctness(base,[{id:'historical-topic',proposal:partial}]);assert.deepEqual(assessment.blockingIds,[]);assert.deepEqual(assessment.relatedIds,['historical-topic']);});

test('creative plans bind exact approved copy, evidence and coherent supported variants',()=>{const {profile,knowledge,plans}=syntheticFixture();assert.equal(plans.length,2);const plan=plans[0]!;assert.equal(plan.variants.length,4);assert.equal(creativeExample(plan,plan.variants[0]!.scenes,{changes:[{field:'storyboard[2].visual',weakness:'Static final explanation',correction:'Use the supported relationship diagram'}]}).scenes[2]!.layout,'relationship');assert.deepEqual(creativeExample(plan,plan.variants[0]!.scenes,{changes:[{field:'hook',weakness:'Bland',correction:'Invent urgency'}]}).scenes,plan.variants[0]!.scenes);assert.ok(plan.variants.every(v=>v.durationSeconds===24));for(const variant of plan.variants){assert.deepEqual(variant.scenes.map(s=>s.displayTexts),variant.storyboard.map(s=>s.onScreenText));assert.ok(variant.storyboard.every(s=>s.evidenceClaimIds.length>0&&s.evidenceClaimIds.every(id=>plan.sourceClaimIds.includes(id))));const proposal=proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01',plan.variants.indexOf(variant));assert.deepEqual(validateCreativeBinding(proposal,plan),[]);assert.equal(validateCampaignProposal(proposal,profile,knowledge,[],[],campaignId+'-gigwise-01').passed,true);}for(const field of ['title','category','caption'] as const){const altered=proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01');altered[field]='Synthetic unapproved metadata';assert.match(validateCreativeBinding(altered,plan).join('; '),/title, category and caption/);}
 assert.equal(compareConcept(proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01'),proposalFor(plan,profile,knowledge,campaignId+'-gigwise-02',1),'variant').classification,'SUPERFICIAL_REWRITE');const correction={changes:[{field:'storyboard[1].visual',weakness:'Comparison obscures the relationship',correction:'Use a relationship diagram'}]},extended=extendCreativePlan(plan,correction);assert.equal(extended.variants.length,5);assert.deepEqual(extended.variants.slice(0,4),plan.variants);assert.deepEqual(extended.sourceClaimIds,plan.sourceClaimIds);assert.deepEqual(extended.requiredAssets,plan.requiredAssets);assert.equal(creativeExample(extended,plan.variants[0]!.scenes,correction).scenes[1]!.layout,'relationship');assert.equal(extendCreativePlan(extended,correction),extended);assert.equal(extendCreativePlan(plan,{changes:[{field:'script.scenes[1].body',weakness:'Plain',correction:'Add unsupported copy'}]}),plan);const accepted=proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01');accepted.acceptedChanges=['c1'];const before=structuredClone(accepted),compiled=compileAcceptedVisualChanges(plan,accepted,{changes:correction.changes.map(c=>({...c,id:'c1'}))})!;assert.ok(compiled);assert.deepEqual(accepted,before);assert.equal(compiled.proposal.script.scenes[1]!.layout,'relationship');assert.deepEqual(compiled.proposal.sourceClaimIds,before.sourceClaimIds);assert.deepEqual(compiled.proposal.script.scenes.map(s=>[s.headline,s.body,s.disclaimer]),before.script.scenes.map(s=>[s.headline,s.body,s.disclaimer]));assert.deepEqual(validateCreativeBinding(compiled.proposal,compiled.plan),[]);assert.equal(compileAcceptedVisualChanges(plan,{...accepted,acceptedChanges:[]},{changes:correction.changes.map(c=>({...c,id:'c1'}))}),null);const option=proposalFor(extended,profile,knowledge,campaignId+'-gigwise-01',4);assert.equal(validateCampaignProposal(option,profile,knowledge,[],[],campaignId+'-gigwise-01').passed,true);assert.deepEqual(validateCreativeBinding(option,extended),[]);const mixed=proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01');mixed.storyboard=structuredClone(plan.variants[1]!.storyboard);assert.match(validateCreativeBinding(mixed,plan).join('; '),/supported composition variant/);const invented=proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01');invented.script.scenes[1]!.displayTexts=['Synthetic unapproved display copy'];assert.equal(validateCampaignProposal(invented,profile,knowledge,[],[],campaignId+'-gigwise-01').passed,false);const asset=proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01');asset.requiredAssets=['synthetic-unapproved-asset'];asset.script.scenes[1]!.assetId='synthetic-unapproved-asset';asset.script.scenes[1]!.layout='media';asset.storyboard[1]!.assetIds=['synthetic-unapproved-asset'];asset.storyboard[1]!.visualType='approved-asset';assert.equal(validateCampaignProposal(asset,profile,knowledge,[],[],campaignId+'-gigwise-01').renderingReady,false);});

test('blocker classification exposes bounded retry eligibility without treating missing evidence as creative recovery',()=>{assert.equal(classifyCampaignBlockers({status:'NEEDS_SOURCE',error:'Approved evidence missing',validation:null}).find(b=>b.kind==='MISSING_APPROVED_EVIDENCE')?.retryEligible,false);assert.equal(classifyCampaignBlockers({status:'NEEDS_REVISION',error:'Duplicate concept',validation:{errors:['Duplicate concept'],missingAssets:[]}}).find(b=>b.kind==='CREATIVE_DISTINCTION')?.retryEligible,true);assert.equal(classifyCampaignBlockers({status:'NEEDS_ASSET',error:'Optional visual unavailable',validation:{errors:[],missingAssets:['original-art']}}).find(b=>b.kind==='MISSING_APPROVED_ASSET')?.retryEligible,false);assert.equal(classifyCampaignBlockers({status:'FAILED',error:'bridge transport failed',validation:{errors:[],missingAssets:[]}}).find(b=>b.kind==='TECHNICAL_FAILURE')?.retryEligible,false);});

test('creative recovery archives immutable history, survives restart, and enforces eligibility and per-attempt budget',async(t)=>{ const temp=await mkdtemp(path.join(os.tmpdir(),'creative-recovery-')),db=path.join(temp,'factory.sqlite'),{profile,knowledge,plans}=syntheticFixture(),center=new PendingCenter();let store=new JobStore(db),service=new CampaignService(store,center,path.join(temp,'exports'),async()=>({allowed:true,reason:'Synthetic fixture'}),async()=>profile,async()=>[]);wire(service,knowledge);try{initializeFixture(service);const id=campaignId+'-gigwise-01',slot=service.slot(id)!,old=proposalFor(plans[0]!,profile,knowledge,id);slot.status='NEEDS_REVISION';slot.contentBaseId=plans[0]!.approach.contentBaseId;slot.snapshot=knowledge;slot.proposal=old;slot.validation=validation(false);slot.versions=[{stage:2,attempt:0,jobId:'synthetic-old-stage2',artifact:'old.json',result:{} as EditorialResult,value:old,parseError:null},{stage:2,attempt:0,jobId:'synthetic-old-stage2b',artifact:'old-b.json',result:{} as EditorialResult,value:old,parseError:null}];saveSlot(store,slot);const queued=await service.recoverCreative([id],'Synthetic operator asks for a distinct direction');assert.equal(queued[0]?.queued,true);const recovered=service.slot(id)!;assert.equal(recovered.proposal,null);assert.equal(recovered.versions.length,2);assert.equal(recovered.creativeRecovery?.previousProposal?.title,old.title);assert.equal(recovered.creativeRecovery?.previousSnapshot?.snapshotHash,knowledge.snapshotHash);assert.equal(recovered.creativeRecovery?.previousStatus,'NEEDS_REVISION');assert.equal(JSON.parse(await readFile(path.join(temp,'exports',campaignId,recovered.creativeRecovery!.artifact),'utf8')).proposal.title,old.title);await assert.rejects(()=>service.review(id,'redirect','Try twice'),/previous creative recovery/);(service as any).lastPoll=0;await service.tick(new Date('2026-10-11T12:00:00Z'));const jobId=service.slot(id)!.job!.jobId;assert.match(jobId,new RegExp(recovered.creativeRecovery!.attemptId));store.close();store=new JobStore(db);service=new CampaignService(store,center,path.join(temp,'exports'),async()=>({allowed:true,reason:'Synthetic fixture'}),async()=>profile,async()=>[]);wire(service,knowledge);assert.equal(service.slot(id)!.job!.jobId,jobId);const revisable=service.slot(id)!;revisable.job=null;revisable.status='NEEDS_REVISION';revisable.proposal=proposalFor(revisable.creativePlan!,profile,knowledge,id);revisable.validation=validation(true);saveSlot(store,revisable);await service.review(id,'revise','Synthetic bounded correction');const once=service.slot(id)!;assert.equal(once.stage,2);once.status='NEEDS_REVISION';once.job=null;once.versions.push({stage:2,attempt:0,jobId:'synthetic-current-a',artifact:'a.json',result:{} as EditorialResult,value:once.proposal,parseError:null,creativeAttemptId:once.creativeRecovery!.attemptId},{stage:2,attempt:0,jobId:'synthetic-current-b',artifact:'b.json',result:{} as EditorialResult,value:once.proposal,parseError:null,creativeAttemptId:once.creativeRecovery!.attemptId});saveSlot(store,once);await assert.rejects(()=>service.review(id,'revise','Third current-attempt revision'),/Maximum two revision rounds/);
 for(const [status,error] of [['APPROVED','done'],['GENERATING','busy']] as const){const other=service.slot(campaignId+'-gigwise-02')!;other.status=status;other.error=error;if(status==='GENERATING')other.job=center.contracts.values().next().value!;saveSlot(store,other);const result=await service.recoverCreative([other.id]);assert.equal(result[0]?.queued,false);}
 const missing=service.slot(campaignId+'-gigwise-03')!;missing.status='FAILED';missing.error='generation failed';saveSlot(store,missing);const incomplete={...knowledge,status:'INCOMPLETE' as const};wire(service,incomplete);assert.equal((await service.recoverCreative([missing.id]))[0]?.queued,false);wire(service,knowledge);const footage={...profile,restrictions:['HUMAN_REQUIRES_GAMEPLAY_FOOTAGE']};const footageService=new CampaignService(store,center,path.join(temp,'exports'),async()=>({allowed:true,reason:'Synthetic fixture'}),async()=>footage,async()=>[]);wire(footageService,knowledge);assert.equal((await footageService.recoverCreative([missing.id]))[0]?.queued,false);const noUnused=service.slot(campaignId+'-gigwise-04')!;noUnused.status='FAILED';noUnused.error='creative distinctness';saveSlot(store,noUnused);for(const [index,base] of plans.entries()){const used=service.slot(campaignId+'-gigwise-0'+(index+5))!;used.contentBaseId=base.approach.contentBaseId;saveSlot(store,used);}assert.match((await service.recoverCreative([noUnused.id]))[0]!.reason,/No unused/);
}finally{store.close();await rm(temp,{recursive:true,force:true});}});

test('a failed stage-two revision preserves the prior deterministically valid creative candidate',async(t)=>{ const temp=await mkdtemp(path.join(os.tmpdir(),'creative-retain-')),store=new JobStore(':memory:'),{profile,knowledge,plans}=syntheticFixture();try{let invalid!:CampaignProposal;const center=new PendingCenter(),service=new CampaignService(store,center,path.join(temp,'exports'),async()=>({allowed:true,reason:'Synthetic fixture'}),async()=>profile,async()=>[]);wire(service,knowledge);initializeFixture(service);const id=campaignId+'-gigwise-01',seed=service.slot(id)!;seed.status='FAILED';seed.error='Synthetic generation failure';seed.snapshot=knowledge;seed.contentBaseId=plans[0]!.approach.contentBaseId;saveSlot(store,seed);assert.equal((await service.recoverCreative([id]))[0]?.queued,true);const slot=service.slot(id)!,valid=proposalFor(slot.creativePlan!,profile,knowledge,id);slot.proposal=valid;slot.validation=validateCampaignProposal(valid,profile,knowledge,[],[],id);slot.stage=2;slot.status='GENERATING';slot.job=(service as any).jobFor(slot,profile);invalid=structuredClone(valid);invalid.title='Guaranteed 99% synthetic result';saveSlot(store,slot);center.submit=async(job:EditorialJob)=>({version:1,jobId:job.jobId,state:'completed',readyForConsumer:true,result:JSON.stringify(invalid),raw:JSON.stringify({model:'qwen3:14b-q8_0',done_reason:'stop'}),error:null,contract:job,lifecycle:{sessionId:job.jobId,state:'STOPPED',verifiedUnloadAt:'2026-10-11T00:00:00Z',cleanupError:null,blocker:null,loadMs:1,inferMs:1,unloadMs:1},createdAt:'2026-10-11T00:00:00Z',completedAt:'2026-10-11T00:01:00Z'});await (service as any).consume(service.slot(id)!);const retained=service.slot(id)!;assert.equal(retained.proposal?.title,valid.title);assert.equal((retained.versions.at(-1)?.value as CampaignProposal).title,invalid.title);assert.equal(retained.validation?.passed,true);}finally{store.close();await rm(temp,{recursive:true,force:true});}});

// Synthetic render fixture only: no model inference, production video or approval.
test('creative frames expose a visible opening, exact approved diagram copy and disclaimer',()=>{const {profile,plans}=syntheticFixture(),plan=plans[0]!;for(const [i,scene] of plan.variants[0]!.scenes.entries()){const html=renderToStaticMarkup(React.createElement(CreativeSceneFrame,{scene,frame:i===0?0:30,profile,disclaimer:scene.disclaimer!}));assert.ok(html.includes(scene.headline));assert.ok(html.includes(scene.disclaimer!));assert.ok(html.includes('data-layout="'+scene.layout+'"'));if(i===0)assert.ok(html.includes('opacity:1'));}});

// Synthetic concurrent operators only; neither operation submits inference.
test('concurrent creative recoveries cannot reserve the same approved concept twice',async(t)=>{const temp=await mkdtemp(path.join(os.tmpdir(),'creative-concurrent-')),store=new JobStore(':memory:'),{profile,knowledge}=syntheticFixture(),center=new PendingCenter(),service=new CampaignService(store,center,path.join(temp,'exports'),async()=>({allowed:true,reason:'Synthetic fixture'}),async()=>profile,async()=>[]);wire(service,knowledge);try{initializeFixture(service);const ids=[campaignId+'-gigwise-01',campaignId+'-gigwise-02'];for(const id of ids){const slot=service.slot(id)!;slot.status='FAILED';slot.error='Synthetic generation failed';saveSlot(store,slot);}const results=await Promise.allSettled(ids.map(id=>service.recoverCreative([id])));assert.equal(results.filter(r=>r.status==='fulfilled').length,1);assert.equal(results.filter(r=>r.status==='rejected'&&/claimed concurrently/.test(String(r.reason))).length,1);assert.equal(ids.filter(id=>service.slot(id)!.creativeRecovery).length,1);assert.equal(center.submissions.length,0);}finally{store.close();await rm(temp,{recursive:true,force:true});}});


test('ambiguous and conflicting accepted visual corrections cannot compile or claim renderer application',()=>{
 const {profile,knowledge,plans}=syntheticFixture(),plan=plans[0]!,proposal=proposalFor(plan,profile,knowledge,campaignId+'-gigwise-01');proposal.acceptedChanges=['c1','c2'];
 const ambiguous={id:'c1',field:'storyboard[1].visual',weakness:'Comparison is plain',correction:'Use relationship layout for scene 3'};
 assert.match(inspectVisualChanges([ambiguous]).issues[0]!.reason,/scene disagree/);assert.equal(compileAcceptedVisualChanges(plan,proposal,{changes:[ambiguous]}),null);
 const conflicts=[{...ambiguous,correction:'Use relationship layout for scene 2'},{...ambiguous,id:'c2',correction:'Use comparison layout for scene 2'}];
 assert.equal(inspectVisualChanges(conflicts).requests.length,0);assert.equal(inspectVisualChanges(conflicts).issues.length,2);assert.equal(compileAcceptedVisualChanges(plan,proposal,{changes:conflicts}),null);
 const slot={factoryCompositions:[{revisionJobId:'q',critiqueJobId:'b',acceptedChangeIds:['c1']}],versions:[{jobId:'q',value:proposal},{jobId:'b',value:{changes:[ambiguous]}}]} as unknown as CampaignSlot;
 assert.match(factoryCompositionIssues(slot).join('; '),/scene disagree/);
});

