 assert.equal(extended.variants.length,5);assert.deepEqual(plan,prior);assert.deepEqual(extended.sourceClaimIds,plan.sourceClaimIds);assert.deepEqual(extended.requiredAssets,plan.requiredAssets);assert.deepEqual(selected.scenes.map(s=>s.seconds),[4,6,6,4]);assert.equal(selected.durationSeconds,20);assert.deepEqual(selected.scenes.map(({seconds,...s})=>s),plan.variants[0]!.scenes.map(({seconds,...s})=>s));const proposal=proposalFor(extended,profile,knowledge,campaignId+'-gigwise-01',4);assert.equal(validateCampaignProposal(proposal,profile,knowledge,[],[],campaignId+'-gigwise-01').passed,true);assert.deepEqual(validateCreativeBinding(proposal,extended),[]);assert.equal(compareConcept(proposal,proposalFor(plan,profile,knowledge,campaignId+'-gigwise-02'),'timing').classification,'EXACT_DUPLICATE');
