// Synthetic decision fixtures. These do not run local inference or approve live work.
function structuredDecision(slot:CampaignSlot,decision:'ACCEPT'|'REVISE'|'RETAIN_PREVIOUS'|'ABSTAIN',specific=false,unsupportedClaims:string[]=[]){
 return {decision,candidateId:slot.id,reasoning:'Scene two is an approved explanation with a readable hold.',evidence:[{reference:'script.scenes[1].seconds',observation:'Scene two holds the same exact text for eight seconds.'}],corrections:specific?[{id:'c1',field:'script.scenes[1].seconds',defect:'An eight-second middle hold slows the approved sequence.',correction:'Reduce scene 2 to 6 seconds using the supported timing option.'}]:[],provenance:{reviewedProposalHash:stableHash(slot.proposal),sourceSnapshotHash:slot.snapshot!.snapshotHash,priorProposalHash:slot.previousValidCandidate&&slot.previousValidCandidate.proposalHash!==stableHash(slot.proposal)?slot.previousValidCandidate.proposalHash:null},validation:{candidateValid:!!slot.validation?.passed,unsupportedClaims},scores:{hook:4,audience:4,distinctiveness:4,evidence:5,feasibility:5,brand:4}};
}
