test('structured ACCEPT skips unnecessary writer inference and final review remains authoritative',async()=>{const f=await editorialServiceFixture();try{const original=JSON.stringify(f.slot.versions[0]);f.slot.job=(f.service as any).jobFor(f.slot,f.profile);saveSlot(f.store,f.slot);f.center.submit=async job=>completedDecision(job,structuredDecision(f.service.slot(f.slot.id)!,'ACCEPT'));await (f.service as any).consume(f.service.slot(f.slot.id));const next=f.service.slot(f.slot.id)!;assert.equal(next.stage,3);assert.equal(next.status,'GENERATING');assert.equal(JSON.stringify(next.versions[0]),original);assert.equal(next.editorialDecisions?.[0]?.decision,'ACCEPT');next.job=(f.service as any).jobFor(next,f.profile);saveSlot(f.store,next);await (f.service as any).consume(f.service.slot(next.id));assert.equal(f.service.slot(next.id)!.status,'AWAITING_APPROVAL');assert.equal(f.store.list().length,0);}finally{f.store.close();await rm(f.temp,{recursive:true,force:true});}});

test('specificity and exhausted revision budget stop at human review without editorial acceptance',async()=>{const f=await editorialServiceFixture();try{f.slot.stage=3;for(let i=0;i<2;i++)f.slot.versions.push({stage:2,attempt:0,jobId:'synthetic-revision-'+i,artifact:'revision.json',result:{} as EditorialResult,value:f.slot.proposal,parseError:null});f.slot.job=(f.service as any).jobFor(f.slot,f.profile);saveSlot(f.store,f.slot);f.center.submit=async job=>completedDecision(job,structuredDecision(f.service.slot(f.slot.id)!,'REVISE',true));await (f.service as any).consume(f.service.slot(f.slot.id));const next=f.service.slot(f.slot.id)!;assert.equal(next.status,'NEEDS_HUMAN_CREATIVE_REVIEW');assert.equal(next.job,null);assert.equal(f.service.overview()!.completedValidated,0);assert.equal(f.service.overview()!.needsHumanCreativeReview,1);assert.equal(f.service.overview()!.slots.find(s=>s.id===next.id)!.reviewStates.editoriallyAccepted,false);await assert.rejects(()=>f.service.review(next.id,'revise','Another round'),/Maximum two/);await assert.rejects(()=>f.service.review(next.id,'approve'),/approval reason/);assert.ok(f.service.overview()!.slots.find(s=>s.id===next.id)!.editorialComparison.originalScript);}finally{f.store.close();await rm(f.temp,{recursive:true,force:true});}});

test('abstention and unsupported-claim concerns stop inference and block approval',async()=>{for(const [decision,claims] of [['ABSTAIN',[]],['ACCEPT',['Claim exceeds source evidence']]] as const){const f=await editorialServiceFixture();try{f.slot.stage=3;f.slot.job=(f.service as any).jobFor(f.slot,f.profile);saveSlot(f.store,f.slot);f.center.submit=async job=>completedDecision(job,structuredDecision(f.service.slot(f.slot.id)!,decision,false,[...claims]));await (f.service as any).consume(f.service.slot(f.slot.id));const next=f.service.slot(f.slot.id)!;assert.equal(next.status,'NEEDS_EVIDENCE');assert.equal(next.job,null);assert.equal(f.service.overview()!.slots.find(s=>s.id===next.id)!.humanApprovalEligible,false);await assert.rejects(()=>f.service.review(next.id,'approve','Override concern'),/evidence concern/);}finally{f.store.close();await rm(f.temp,{recursive:true,force:true});}}});

test('previous valid candidate persists across restart; invalid raw revision is excluded from comparison',async()=>{const f=await editorialServiceFixture();try{const prior=structuredClone(f.slot.proposal!);f.slot.proposal!.script.scenes[1]!.seconds=6;f.slot.proposal!.durationSeconds-=2;f.slot.validation=validateCampaignProposal(f.slot.proposal!,f.profile,f.knowledge,[],[],f.slot.id);f.slot.previousValidCandidate={proposal:prior,proposalHash:stableHash(prior),snapshotHash:f.knowledge.snapshotHash};f.slot.stage=3;const invalid=structuredClone(prior);invalid.script.scenes[1]!.body='Unsupported claim';f.slot.versions.push({stage:2,attempt:0,jobId:'invalid-raw-revision',artifact:'invalid.json',result:{} as EditorialResult,value:invalid,parseError:null});saveSlot(f.store,f.slot);f.store.close();f.store=new JobStore(path.join(f.temp,'factory.sqlite'));const again=new CampaignService(f.store,f.center,path.join(f.temp,'exports'),async()=>({allowed:true,reason:'Synthetic fixture'}),async()=>f.profile,async()=>[]);wire(again,f.knowledge);const persisted=again.slot(f.slot.id)!,job=(again as any).jobFor(persisted,f.profile);assert.ok(job.prompt.includes(stableHash(prior)));assert.ok(!job.prompt.includes('Unsupported claim'));persisted.job=job;saveSlot(f.store,persisted);f.center.submit=async job=>completedDecision(job,structuredDecision(again.slot(persisted.id)!,'RETAIN_PREVIOUS'));await (again as any).consume(again.slot(persisted.id));const next=again.slot(persisted.id)!;assert.equal(stableHash(next.proposal),stableHash(prior));assert.equal(next.status,'NEEDS_HUMAN_CREATIVE_REVIEW');assert.equal((next.versions.find(v=>v.jobId==='invalid-raw-revision')!.value as CampaignProposal).script.scenes[1]!.body,'Unsupported claim');}finally{f.store.close();await rm(f.temp,{recursive:true,force:true});}});

test('distinctness v2 uses actual asset sequence and never rejects on direction ID alone',()=>{const a=concept('organize a receipt date merchant and business purpose','connect the supporting receipt to its expense');const b=concept('review category groups before exporting an approved record','filter the record list by a separate category workflow');a.creativeApproach={directionId:'shared-feature',contentBaseId:'approved-feature',narrative:'problem/solution',visualTreatment:'sequence'};b.creativeApproach={...a.creativeApproach,narrative:'educational explainer'};assert.equal(compareConcept(a,b,'different-execution').blocking,false);const old=assessDistinctness(a,[{id:'same',proposal:a}]);assert.equal(old.method,'structured-composition-v2');assert.equal(old.blockingIds.length,1);const media=structuredClone(a),other=structuredClone(a);media.script!.scenes[1]!.assetId='approved-clip-a';other.script!.scenes[1]!.assetId='approved-clip-b';assert.equal(compareConcept(media,other,'different-approved-footage').measures.visualSequenceEqual,false);assert.equal(compareConcept(media,other,'different-approved-footage').classification,'SUPERFICIAL_REWRITE');});


test('explicit creative-review handoff archives original record and requires fresh safety checks',async()=>{const f=await editorialServiceFixture();try{f.slot.status='NEEDS_REVISION';f.slot.stage=3;f.slot.versions.push({stage:3,attempt:0,jobId:'synthetic-final-review',artifact:'final.json',result:{} as EditorialResult,value:structuredDecision(f.slot,'REVISE') as any,parseError:null});saveSlot(f.store,f.slot);const original=JSON.stringify(f.service.slot(f.slot.id));await f.service.review(f.slot.id,'creative-review','Human should compare the approved hook and pacing.');const next=f.service.slot(f.slot.id)!;assert.equal(next.status,'NEEDS_HUMAN_CREATIVE_REVIEW');assert.equal(JSON.stringify(next.versions),JSON.stringify(f.slot.versions));const files=await readdir(path.join(f.temp,'exports',campaignId,'editorial-handoffs'));const archived=JSON.parse(await readFile(path.join(f.temp,'exports',campaignId,'editorial-handoffs',files[0]!), 'utf8'));assert.equal(JSON.stringify(archived.originalSlot),original);assert.equal(archived.editoriallyAccepted,false);assert.equal(f.service.overview()!.completedValidated,0);assert.equal(f.store.list().length,0);}finally{f.store.close();await rm(f.temp,{recursive:true,force:true});}});


test('generic initial feedback skips writer inference and preserves both assessments',async()=>{const f=await editorialServiceFixture();try{f.slot.job=(f.service as any).jobFor(f.slot,f.profile);saveSlot(f.store,f.slot);f.center.submit=async job=>completedDecision(job,structuredDecision(f.service.slot(f.slot.id)!,'REVISE'));await (f.service as any).consume(f.service.slot(f.slot.id));const next=f.service.slot(f.slot.id)!;assert.equal(next.stage,3);assert.equal(next.versions.filter(v=>v.stage===2).length,0);assert.equal(next.validation?.passed,true);assert.equal(next.editorialDecisions?.[0]?.actionableRevision,false);assert.ok(f.service.overview()!.slots.find(s=>s.id===next.id)!.editorialComparison.bonsaiFeedback.length);}finally{f.store.close();await rm(f.temp,{recursive:true,force:true});}});
